   p=re.sub(r'(?<=\d)(?=(?:entrées|existants|cibles|réserves|aperçus|leçons|manifestes|points|rubriques|tests|secondes|minutes|lectures|originaux|fenêtres|quiz|Pareto|sciences|sections|fichiers|heures|h\b))',' ',p)
